{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE TABLE IF NOT EXISTS pronk-wh.maplemonk.pronk_sku_master ( skucode STRING, name STRING, category STRING, sub_category STRING ); CREATE TABLE IF NOT EXISTS pronk-wh.maplemonk.pronk_final_sku_master ( skucode STRING, product_name STRING, category STRING, sub_category STRING, marketplace STRING, commonsku STRING, marketplace_sku string, DATA_SOURCE STRING, category_code STRING, MRP FLOAT64, TAX_RATE FLOAT64 ); CREATE OR REPLACE TABLE pronk-wh.maplemonk.PRONK_AMAZON_FACT_ITEMS_INTERMEDIATE AS SELECT \'Custom_Amazon_Seller_Partner_ASP_pronk\' AS shop_name, cast(amazon_order_id as string) order_id, cast(amazon_order_id AS string) order_name, NULL AS customer_id, NULL AS phone, NULL AS tags, NULL AS line_item_id, REGEXP_REPLACE(cast(Sku as string),\'-$\', \'\') sku, ASIN AS product_id, cast(Currency as string) Currency, CASE WHEN order_status IN (\'Shipped - Returned to Seller\', \'Shipped - Returning to Seller\', \'Shipped - Rejected by Buyer\', \'Shipped - Damaged\') THEN 1 ELSE 0 END AS is_refund, cast(UPPER(ship_city) as string) AS city, cast(UPPER(ship_state) as string) AS state, cast(ship_postal_code as string) AS pincode, upper(cast(product_name as string)) AS product_name, NULL AS category, cast(order_status as string )order_status, CAST(FORMAT_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', PARSE_TIMESTAMP(\'%Y-%m-%dT%H:%M:%S%Ez\', purchase_date)) AS DATETIME) AS order_timestamp, IFNULL(SAFE_CAST(item_price AS FLOAT64), 0) AS line_item_sales, IFNULL(SAFE_CAST(shipping_price AS FLOAT64), 0) AS shipping_price, IFNULL(SAFE_CAST(quantity AS FLOAT64), 0) AS quantity, IFNULL(SAFE_CAST(item_tax AS FLOAT64), 0) AS tax, SAFE_DIVIDE(IFNULL(SAFE_CAST(item_tax AS FLOAT64), 0), IFNULL(SAFE_CAST(item_tax AS FLOAT64), 0) + IFNULL(SAFE_CAST(item_price AS FLOAT64), 0)) AS tax_rate, IFNULL(safe_CAST(item_promotion_discount AS FLOAT64), 0) AS discount, SAFE_DIVIDE(IFNULL(SAFE_CAST(item_promotion_discount AS FLOAT64), 0), (1 - (SAFE_DIVIDE(IFNULL(SAFE_CAST(item_tax AS FLOAT64), 0), IFNULL(SAFE_CAST(item_tax AS FLOAT64), 0) + IFNULL(SAFE_CAST(item_price AS FLOAT64), 0))) )) AS discount_before_tax, NULL AS gross_sales_after_tax, IFNULL(SAFE_CAST(item_price AS FLOAT64), 0) - (SAFE_DIVIDE(IFNULL(SAFE_CAST(item_promotion_discount AS FLOAT64), 0), (1 - (SAFE_DIVIDE(IFNULL(SAFE_CAST(item_tax AS FLOAT64), 0), IFNULL(SAFE_CAST(item_tax AS FLOAT64), 0) + IFNULL(SAFE_CAST(item_price AS FLOAT64), 0))) ))) AS gross_sales_before_tax, NULL AS net_sales_before_tax, IFNULL(SAFE_CAST(item_price AS FLOAT64), 0) AS total_sales, \'Amazon\' AS source, NULL AS landing_utm_medium, NULL AS landing_utm_source, NULL AS landing_utm_campaign, NULL AS referring_utm_medium, NULL AS referring_utm_source, NULL AS landing_utm_channel, NULL AS referring_utm_channel, NULL AS final_utm_channel, NULL AS new_customer_flag, NULL AS acquisition_channel, NULL AS acquisition_product, IFNULL(SAFE_CAST(shipping_tax AS FLOAT64), 0) AS shipping_tax, IFNULL(SAFE_CAST(ship_promotion_discount AS FLOAT64), 0) AS ship_promotion_discount, IFNULL(SAFE_CAST(gift_wrap_price AS FLOAT64), 0) AS gift_wrap_price, IFNULL(SAFE_CAST(gift_wrap_tax AS FLOAT64), 0) AS gift_wrap_tax, cast(null as string) AS Email, cast(null as string) AS Name, cast(null as string) as Recipient_Name FROM ( SELECT *, purchase_date AS Purchase_datetime_PDT FROM pronk-wh.maplemonk.Custom_Amazon_Seller_Partner_pronk_amazon_GET_FLAT_FILE_ALL_ORDERS_DATA_BY_LAST_UPDATE_GENERAL ) X; CREATE OR REPLACE TABLE pronk-wh.maplemonk.pronk_AMAZON_FACT_ITEMS AS SELECT fi.* ,p1.product_name AS product_name_final ,UPPER(COALESCE(cast(p.CATEGORY as string),maplemonk.get_caategory(coalesce(fi.SKU,\'\')))) AS product_category ,UPPER(coalesce(cast(p.sub_category as string),maplemonk.get_sub_category(coalesce(fi.SKU,\'\')))) AS product_sub_category ,Upper(coalesce(p.colour,maplemonk.get_color(coalesce(fi.SKU,\'\')))) as Product_Colour ,Upper(coalesce(p.size,maplemonk.get_size(coalesce(fi.SKU,\'\')))) as Product_Size ,Upper(coalesce(p.dt_code,maplemonk.get_dt_code(coalesce(fi.SKU,\'\')))) as Product_DT_Code ,Upper(coalesce(p.gender,maplemonk.get_gender(coalesce(fi.SKU,\'\')))) as Gender ,p.commonsku ,upper(p1.product_type) as Product_Type FROM pronk-wh.maplemonk.pronk_AMAZON_FACT_ITEMS_INTERMEDIATE fi left join (select * from (select replace(easycom,\' \',\'\') skucode, replace(accounting_skus,\'#N/A\',\'\') commonsku, cast(category as string) category, cast(sub_category as string) as sub_category, cast(colour as string) as colour, cast(size as string) as size, cast(dt_code as string) as dt_code, cast(gender as string) as gender, row_number() over (partition by replace(easycom,\' \',\'\') order by 1) rw from pronk-wh.maplemonk.PRONK_sku_master) where rw = 1 ) p on lower(replace(fi.sku,\' \',\'\')) = lower(replace(p.skucode,\' \',\'\')) left join (select * from (select product_name, product_type, sku, row_number() over (partition by replace(sku,\' \',\'\') order by 1) rw from pronk-wh.maplemonk.PRONK_product_master) where rw = 1 )p1 on lower(replace(fi.sku,\' \',\'\')) = lower(replace(p1.sku,\' \',\'\')) ;",
                    "transaction": true
